# ─────────────────────────────────────────────────────────

# Use like: delta, confidence, class, probabilities = predict_delta_and_confidence(product, x).
# delta = the predicted price change from mid
# confidence = the model's confidence in that prediction (0.0 to 1.0)
# class = the predicted class index (0 to 7)
# probabilities = the full softmax output for all classes (list of 8 floats)

def predict_delta(product, x): 
    if product == "ASH_COATED_OSMIUM":
        logits = MLP_forward_logits(
            x,
            OSMIUM_MEAN, OSMIUM_SCALE,
            OSMIUM_W1, OSMIUM_B1,
            OSMIUM_W2, OSMIUM_B2,
            OSMIUM_W3, OSMIUM_B3,
            OSMIUM_W4, OSMIUM_B4,
        )
        probs = softmax(logits)
        cls = argmax_index(logits)
        deltaPrice = OSMIUM_CLASS_VALUES[cls]
        confidence = probs[cls]

        return deltaPrice, confidence, cls, probs

    elif product == "INTARIAN_PEPPER_ROOT":
        logits = MLP_forward_logits(
            x,
            ROOT_MEAN, ROOT_SCALE,
            ROOT_W1, ROOT_B1,
            ROOT_W2, ROOT_B2,
            ROOT_W3, ROOT_B3,
            ROOT_W4, ROOT_B4,
        )
        probs = softmax(logits)
        cls = argmax_index(probs)
        deltaPrice = ROOT_CLASS_VALUES[cls]
        confidence = probs[cls]
        return deltaPrice, confidence, cls, probs

    else:
        return 0.0, 0.0, -1, []

def predict_price(product, x, mid_price):
    return mid_price + predict_delta(product, x)[0]

def extract_features(od: OrderDepth, market_trades, trader_state, product):
    """
    Build the exact 18-feature vector expected by the trained MLP.
    Returns: (features, mid, trader_state)
    """

    # ── Best bid / ask ─────────────────────────────────────────────
    bid_price_1 = float(max(od.buy_orders.keys())) if od.buy_orders else 0.0
    ask_price_1 = float(min(od.sell_orders.keys())) if od.sell_orders else 0.0

    bid_volume_1 = float(od.buy_orders.get(bid_price_1, 0)) if od.buy_orders else 0.0
    ask_volume_1 = float(abs(od.sell_orders.get(ask_price_1, 0))) if od.sell_orders else 0.0

    # Bail out cleanly if book is broken
    if bid_price_1 <= 0 or ask_price_1 <= 0:
        mid = 0.0
        features = [0.0] * 18
        return features, mid, trader_state

    mid = 0.5 * (bid_price_1 + ask_price_1)

    # ── Trades ─────────────────────────────────────────────────────
    trades = market_trades.get(product, [])

    trade_count = float(len(trades))
    trade_qty = float(sum(abs(t.quantity) for t in trades))

    if trade_qty > 0:
        trade_value = float(sum(float(t.price) * abs(t.quantity) for t in trades))
        trade_vwap = trade_value / trade_qty
    else:
        trade_vwap = mid

    # ── Engineered features ────────────────────────────────────────
    spread = ask_price_1 - bid_price_1

    imbalance = bid_volume_1 - ask_volume_1
    total_vol_1 = bid_volume_1 + ask_volume_1
    imbalance_ratio = (
        imbalance / (total_vol_1 + 1e-6)
        if total_vol_1 > 0 else 0.0
    )

    microprice = (
        (ask_price_1 * bid_volume_1 + bid_price_1 * ask_volume_1) / (total_vol_1 + 1e-6)
        if total_vol_1 > 0 else mid
    )
    micro_diff = microprice - mid

    mid_minus_vwap = mid - trade_vwap

    # ── Top 3 book totals ──────────────────────────────────────────
    sorted_bids = sorted(od.buy_orders.keys(), reverse=True)[:3]
    sorted_asks = sorted(od.sell_orders.keys())[:3]

    total_bid_vol_3 = float(sum(float(od.buy_orders[p]) for p in sorted_bids))
    total_ask_vol_3 = float(sum(float(abs(od.sell_orders[p])) for p in sorted_asks))

    book_total_3 = total_bid_vol_3 + total_ask_vol_3
    book_imbalance_3 = (
        (total_bid_vol_3 - total_ask_vol_3) / (book_total_3 + 1e-6)
        if book_total_3 > 0 else 0.0
    )

    # ── Previous tick state ────────────────────────────────────────
    prev_key = f"prev_{product}"
    prev = trader_state.get(prev_key, {})

    prev_mid = float(prev.get("mid", mid))
    prev_mid_change = mid - prev_mid

    prev_spread = float(prev.get("spread", spread))
    prev_imbalance_ratio = float(prev.get("imbalance_ratio", imbalance_ratio))

    # Store current values for next tick
    trader_state[prev_key] = {
        "mid": mid,
        "spread": spread,
        "imbalance_ratio": imbalance_ratio,
    }

    # ── EXACT training feature order ───────────────────────────────
    features = [
        bid_price_1, bid_volume_1,
        ask_price_1, ask_volume_1,
        trade_count, trade_qty, trade_vwap,
        spread, imbalance, imbalance_ratio,
        micro_diff, mid_minus_vwap,
        total_bid_vol_3, total_ask_vol_3, book_imbalance_3,
        prev_mid_change, prev_spread, prev_imbalance_ratio,
    ]

    return features, mid, trader_state

# ---------------------------------------------------------------------
#  Logger
# ---------------------------------------------------------------------

class Logger:
    def __init__(self) -> None:
        self.logs = ""
        self.max_log_length = 3750

    def print(self, *objects: Any, sep: str = " ", end: str = "\n") -> None:
        self.logs += sep.join(map(str, objects)) + end

    def flush(self, state: TradingState, orders: dict[Symbol, list[Order]], conversions: int, trader_data: str) -> None:
        base_length = len(
            self.to_json([
                self.compress_state(state, ""),
                self.compress_orders(orders),
                conversions, "", "",
            ])
        )
        max_item_length = (self.max_log_length - base_length) // 3
        print(
            self.to_json([
                self.compress_state(state, self.truncate(state.traderData, max_item_length)),
                self.compress_orders(orders),
                conversions,
                self.truncate(trader_data, max_item_length),
                self.truncate(self.logs, max_item_length),
            ])
        )
        self.logs = ""

    def compress_state(self, state: TradingState, trader_data: str) -> list[Any]:
        return [
            state.timestamp, trader_data,
            self.compress_listings(state.listings),
            self.compress_order_depths(state.order_depths),
            self.compress_trades(state.own_trades),
            self.compress_trades(state.market_trades),
            state.position,
            self.compress_observations(state.observations),
        ]

    def compress_listings(self, listings: dict[Symbol, Listing]) -> list[list[Any]]:
        return [[l.symbol, l.product, l.denomination] for l in listings.values()]

    def compress_order_depths(self, order_depths: dict[Symbol, OrderDepth]) -> dict[Symbol, list[Any]]:
        return {s: [od.buy_orders, od.sell_orders] for s, od in order_depths.items()}

    def compress_trades(self, trades: dict[Symbol, list[Trade]]) -> list[list[Any]]:
        return [[t.symbol, t.price, t.quantity, t.buyer, t.seller, t.timestamp]
                for arr in trades.values() for t in arr]

    def compress_observations(self, observations: Observation) -> list[Any]:
        conv_obs = {}
        for product, obs in observations.conversionObservations.items():
            conv_obs[product] = [
                obs.bidPrice, obs.askPrice, obs.transportFees,
                obs.exportTariff, obs.importTariff, obs.sugarPrice, obs.sunlightIndex,
            ]
        return [observations.plainValueObservations, conv_obs]

    def compress_orders(self, orders: dict[Symbol, list[Order]]) -> list[list[Any]]:
        return [[o.symbol, o.price, o.quantity] for arr in orders.values() for o in arr]

    def to_json(self, value: Any) -> str:
        return json.dumps(value, cls=ProsperityEncoder, separators=(",", ":"))

    def truncate(self, value: str, max_length: int) -> str:
        lo, hi = 0, min(len(value), max_length)
        out = ""
        while lo <= hi:
            mid = (lo + hi) // 2
            candidate = value[:mid]
            if len(candidate) < len(value):
                candidate += "..."
            if len(json.dumps(candidate)) <= max_length:
                out = candidate
                lo = mid + 1
            else:
                hi = mid - 1
        return out


logger = Logger()

# ---------------------------------------------------------------------
#  CONFIGURATION
# ---------------------------------------------------------------------

POSITION_LIMITS = {
    "ASH_COATED_OSMIUM": 80,
    "INTARIAN_PEPPER_ROOT": 80,
}

# -- OSMIUM: tight MM (from teammate) + position-aware edge (from us) --
OSMIUM_FAIR      = 10_000
OSMIUM_MM_HALF   = 1       # Tight quotes: 9999 / 10001
OSMIUM_TAKE_EDGE = 2       # Take anything beyond ±3=2 from fair
OSMIUM_INV_SKEW  = 0.3     # Gentle skew
OSMIUM_MAX_SKEW  = 4

# -- PEPPER: max-long trend capture (from teammate) -------------------
PEPPER_SLOPE             = 1.0 / 1000
PEPPER_BUY_EDGE          = 2     # Buy even at fair+2 - trend recovers in 8s
PEPPER_SELL_SPIKE        = 15    # Only sell on massive spikes
PEPPER_PASSIVE_BID_ABOVE = 1     # Bid at fair+1 to attract sellers


# ---------------------------------------------------------------------
#  TRADER
# ---------------------------------------------------------------------

class Trader:

    def run(self, state: TradingState):
        result: Dict[Symbol, List[Order]] = {}
        trader_state = {}
        if state.traderData:
            try:
                trader_state = json.loads(state.traderData)
            except Exception:
                trader_state = {}
        for product in state.order_depths:
            od: OrderDepth = state.order_depths[product]
            position = state.position.get(product, 0)
            limit = POSITION_LIMITS.get(product, 80)
            try:
                if product == "ASH_COATED_OSMIUM":
                    result[product] = self.trade_osmium(od, position, limit)
                elif product == "INTARIAN_PEPPER_ROOT":
                    result[product], trader_state = self.trade_pepper(
                        od, position, limit, state.timestamp, trader_state,
                        state.market_trades
                    )
            except Exception as e:
                result[product] = []
                logger.print(f"ERROR {product}: {e}")
        trader_data = json.dumps(trader_state)
        conversions = 0
        logger.flush(state, result, conversions, trader_data)
        return result, conversions, trader_data

    # =============================================================
    #  ASH_COATED_OSMIUM - Tight MM + Position-Aware Edge
    #
    #  Teammate's ±2 spread (tighter = more fills on live)
    #  + Our position-aware edge (protective when loaded)
    #  + Aggressive-first ordering (from our v3)
    # =============================================================

    def trade_osmium(self, od: OrderDepth, position: int, limit: int) -> List[Order]:
        orders: List[Order] = []
        fair = OSMIUM_FAIR

        # Position-aware aggressive edge (from our v3)
        edge = OSMIUM_TAKE_EDGE
        if abs(position) > int(limit * 0.7):
            edge += 1

        # -- STEP 1: Aggressive takes first -----------------------
        if od.sell_orders:
            for ask in sorted(od.sell_orders.keys()):
                if ask < fair - edge and position < limit:
                    qty = min(-od.sell_orders[ask], limit - position)
                    if qty > 0:
                        orders.append(Order("ASH_COATED_OSMIUM", ask, qty))
                        position += qty
                        logger.print(f"OSM TAKE BUY {qty}@{ask}")
                else:
                    break

        if od.buy_orders:
            for bid in sorted(od.buy_orders.keys(), reverse=True):
                if bid > fair + edge and position > -limit:
                    qty = min(od.buy_orders[bid], limit + position)
                    if qty > 0:
                        orders.append(Order("ASH_COATED_OSMIUM", bid, -qty))
                        position -= qty
                        logger.print(f"OSM TAKE SELL {qty}@{bid}")
                else:
                    break

        # -- STEP 2: Tight passive MM with remaining capacity -----
        skew = -position * OSMIUM_INV_SKEW
        skew = max(-OSMIUM_MAX_SKEW, min(OSMIUM_MAX_SKEW, skew))

        bid_px = int(round(fair - OSMIUM_MM_HALF + skew))
        ask_px = int(round(fair + OSMIUM_MM_HALF + skew))

        bid_px = min(bid_px, fair - 1)
        ask_px = max(ask_px, fair + 1)

        bid_qty = limit - position
        ask_qty = limit + position

        if bid_qty > 0:
            orders.append(Order("ASH_COATED_OSMIUM", bid_px, bid_qty))
        if ask_qty > 0:
            orders.append(Order("ASH_COATED_OSMIUM", ask_px, -ask_qty))

        return orders

    # =============================================================
    #  INTARIAN_PEPPER_ROOT - Max Long Trend Capture
    #
    #  Teammate's core insight: hold max long, trend does the work.
    #  + Our weighted mid for more accurate fair value
    #  + Slightly faster EMA adaptation (0.008 vs 0.005)
    # =============================================================

    def trade_pepper(self, od: OrderDepth, position: int, limit: int,
                 timestamp: int, trader_state: dict, market_trades) -> tuple[List[Order], dict]:
        orders: List[Order] = []
        best_bid = max(od.buy_orders.keys()) if od.buy_orders else None
        best_ask = min(od.sell_orders.keys()) if od.sell_orders else None
        if best_bid is None and best_ask is None:
            return orders, trader_state

       # -- MLP fair value ----------------------------------------
        try:
            x, mid = extract_features(od, market_trades, trader_state, "INTARIAN_PEPPER_ROOT")
            if mid == 0:
                return orders, trader_state
            fair = predict_price("INTARIAN_PEPPER_ROOT", x, mid)
            delta = predict_delta("INTARIAN_PEPPER_ROOT", x)
            if delta > 0.5:
                buy_edge = PEPPER_BUY_EDGE + 2
            else:
                buy_edge = PEPPER_BUY_EDGE - 1
        except:
            # Fallback to simple mid
            if best_bid is not None and best_ask is not None:
                mid = (best_bid + best_ask) / 2
            else:
                mid = float(best_bid or best_ask)
            fair = mid
            buy_edge = PEPPER_BUY_EDGE
    
        logger.print(f"PEPPER t={timestamp} fair={fair:.1f} mid={mid:.1f} pos={position}")

        # -- 1. Aggressive BUY: take any ask <= fair + BUY_EDGE ----
        if od.sell_orders:
            for ask in sorted(od.sell_orders.keys()):
                if ask <= fair + buy_edge and position < limit:
                    qty = min(-od.sell_orders[ask], limit - position)
                    if qty > 0:
                        orders.append(Order("INTARIAN_PEPPER_ROOT", ask, qty))
                        position = position + qty
                        logger.print(f"PEPPER BUY {qty}@{ask} fair={fair:.1f}")
                else:
                    break
        # -- 2. Spike sell: only if bid far above fair, never go short --
        if od.buy_orders and position > 0:
            for bid in sorted(od.buy_orders.keys(), reverse=True):
                if bid > fair + PEPPER_SELL_SPIKE:
                    qty = min(od.buy_orders[bid], position)
                    if qty > 0:
                        orders.append(Order("INTARIAN_PEPPER_ROOT", bid, -qty))
                        position = position - qty
                        logger.print(f"PEPPER SPIKE SELL {qty}@{bid} fair={fair:.1f}")
                else:
                    break
        # -- 3. Passive BUY: fill remaining capacity above fair ---
        remaining = limit - position
        if remaining > 0:
            passive_bid = int(round(fair + PEPPER_PASSIVE_BID_ABOVE))
            if best_ask is not None:
                passive_bid = min(passive_bid, best_ask - 1)
            orders.append(Order("INTARIAN_PEPPER_ROOT", passive_bid, remaining))
        return orders, trader_state
